local P=table.concat(PT) PT=nil
local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local T={}
for i=1,#A do T[A:byte(i)]=i-1 end
local o,n,acc={},0,0
for i=1,#P do
 local v=T[P:byte(i)]
 if v then acc=acc*64+v n=n+1
  if n==4 then o[#o+1]=string.char(math.floor(acc/65536)%256,math.floor(acc/256)%256,acc%256) acc,n=0,0 end
 end
end
if n==2 then o[#o+1]=string.char(math.floor(acc/16)%256)
elseif n==3 then o[#o+1]=string.char(math.floor(acc/1024)%256,math.floor(acc/4)%256) end
local cipher=table.concat(o)
P=nil A=nil T=nil o=nil
local function bx(a,b)
 local r,p=0,1
 while a>0 or b>0 do if a%2~=b%2 then r=r+p end a=math.floor(a/2) b=math.floor(b/2) p=p*2 end
 return r
end
if bit32 and bit32.bxor then bx=bit32.bxor end
local M={}
for i=0,767 do M[i+1]=bx(bx(K1:byte(i%48+1),K2:byte(i%16+1)),(i*89+37)%256) end
local sourceLen=780071 expected=3336381807 sum=0
local o={}
for i=1,#cipher do local b=bx(cipher:byte(i),M[(i-1)%768+1]) sum=(sum+b*i)%4294967291 o[i]=string.char(b) end
local source=table.concat(o)
cipher=nil M=nil
if #source~=sourceLen or sum~=expected then return fail("integrity "..#source.."/"..sourceLen.." sum "..sum.."/"..expected) end
local fn,err=(loadstring or load)(source)
if not fn then return fail(tostring(err or "load failed")) end
local ok,rerr=pcall(fn)
if not ok then fail(tostring(rerr or "execution failed")) end
